import{_ as e}from"./chunks/theme.DQAo4dYo.js";import{_ as s,o as t,c as n,ai as i}from"./chunks/framework.DQi1ytmF.js";const m=JSON.parse('{"title":"Press Kit","description":"","frontmatter":{},"headers":[],"relativePath":"resources/press-kit.md","filePath":"resources/press-kit.md"}'),r={name:"resources/press-kit.md"};function o(l,a,c,p,d,h){return t(),n("div",null,[...a[0]||(a[0]=[i('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/resources/press-kit.md for this page in Markdown format</div><h1 id="press-kit" tabindex="-1">Press Kit <a class="header-anchor" href="#press-kit" aria-label="Permalink to &quot;Press Kit&quot;">​</a></h1><p>Resources and information about <code>@craft-ts/core</code> for articles, presentations, and sharing.</p><h2 id="project-description" tabindex="-1">Project description <a class="header-anchor" href="#project-description" aria-label="Permalink to &quot;Project description&quot;">​</a></h2><h3 id="short-description" tabindex="-1">Short description <a class="header-anchor" href="#short-description" aria-label="Permalink to &quot;Short description&quot;">​</a></h3><p><code>@craft-ts/core</code> is a reactive TypeScript toolkit for URL, client, and server state. Its primitives make dependencies explicit and keep application code fully type-safe.</p><h3 id="long-description" tabindex="-1">Long description <a class="header-anchor" href="#long-description" aria-label="Permalink to &quot;Long description&quot;">​</a></h3><p><code>@craft-ts/core</code> brings state, asynchronous work, services, forms, routing, and testing into one composable model. Named generators and typed insertions make the dependency graph visible to both the compiler and development tools. The result is granular reactivity, typed failures, optimistic updates, persistence, and predictable loading states without repetitive coordination code.</p><h2 id="key-features" tabindex="-1">Key features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key features&quot;">​</a></h2><ul><li>✅ <strong>Type-safe</strong> — TypeScript inference minimizes manual declarations</li><li>✅ <strong>Composable</strong> — primitives and insertions share one composition model</li><li>✅ <strong>Granular</strong> — updates target the readers that actually depend on them</li><li>✅ <strong>Declarative</strong> — state, effects, forms, and routes are explicit data</li><li>✅ <strong>Observable</strong> — the same graph powers logging, tracing, and diagnostics</li><li>✅ <strong>Testable</strong> — services, components, and architecture contracts can be tested independently</li></ul><h2 id="logo-and-brand-assets" tabindex="-1">Logo and brand assets <a class="header-anchor" href="#logo-and-brand-assets" aria-label="Permalink to &quot;Logo and brand assets&quot;">​</a></h2><p><img src="'+e+`" alt="craft-ts Logo"></p><ul><li><a href="/craft/assets/craft-ts-logo.png">Download logo</a></li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @craft-ts/core@beta</span></span></code></pre></div><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><strong>GitHub</strong>: <a href="https://github.com/craft-ts/craft-ts" target="_blank" rel="noreferrer">github.com/craft-ts/craft-ts</a></li><li><strong>Documentation</strong>: <a href="https://craft-ts.github.io/craft/" target="_blank" rel="noreferrer">craft-ts.github.io/craft/</a></li><li><strong>NPM</strong>: <a href="https://npmjs.com/package/@craft-ts/core" target="_blank" rel="noreferrer">npmjs.com/package/@craft-ts/core</a></li></ul><h2 id="social-media" tabindex="-1">Social media <a class="header-anchor" href="#social-media" aria-label="Permalink to &quot;Social media&quot;">​</a></h2><h3 id="linkedin" tabindex="-1">LinkedIn <a class="header-anchor" href="#linkedin" aria-label="Permalink to &quot;LinkedIn&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Excited to share @craft-ts/core — a type-safe toolkit for state, services,</span></span>
<span class="line"><span>forms, routing, and asynchronous work.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Craft makes dependencies explicit and gives every primitive a predictable</span></span>
<span class="line"><span>lifecycle, typed failures, and composable behaviour:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>• Reactive local and server state</span></span>
<span class="line"><span>• URL state with typed codecs</span></span>
<span class="line"><span>• Optimistic mutations</span></span>
<span class="line"><span>• Typed forms and validation</span></span>
<span class="line"><span>• Explicit service composition</span></span>
<span class="line"><span>• Architecture checks and observability</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Check it out: [link]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#TypeScript #WebDevelopment #OpenSource</span></span></code></pre></div><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>MIT License — free for personal and commercial use.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>Created and maintained by Romain Geffrault.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Issues</strong>: <a href="https://github.com/craft-ts/craft-ts/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li><strong>Discussions</strong>: <a href="https://github.com/craft-ts/craft-ts/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a></li></ul>`,26)])])}const g=s(r,[["render",o]]);export{m as __pageData,g as default};
